package com.exampro.service;
import com.exampro.dto.ApiDtos.*;import com.exampro.entity.*;import com.exampro.exception.*;import com.exampro.repository.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service @Transactional public class AttemptService {private final AttemptRepository attempts;private final ExamRepository exams;private final UserRepository users;private final QuestionRepository questions;public AttemptService(AttemptRepository a,ExamRepository e,UserRepository u,QuestionRepository q){attempts=a;exams=e;users=u;questions=q;}
 @Transactional public AttemptResponse start(String email,Long examId){AppUser u=users.findByEmailIgnoreCase(email).orElseThrow(()->new NotFoundException("User not found"));Exam e=exams.findById(examId).orElseThrow(()->new NotFoundException("Exam not found"));if(u.getRole()!=Role.STUDENT)throw new BadRequestException("Only students can start an attempt");if(!e.isAvailableNow())throw new BadRequestException("Exam is not currently available");if(e.getQuestions().isEmpty())throw new BadRequestException("Exam has no questions");if(attempts.existsByUserIdAndExamIdAndStatus(u.getId(),e.getId(),Attempt.Status.IN_PROGRESS))throw new BadRequestException("You already have an in-progress attempt");Attempt a=new Attempt();a.setUser(u);a.setExam(e);return dto(attempts.save(a));}
 @Transactional public AttemptResponse save(String email,Long id,SaveAnswersRequest r){Attempt a=owned(email,id);ensureActive(a);for(AnswerRequest ar:r.answers()){Question q=a.getExam().getQuestions().stream().filter(x->x.getId().equals(ar.questionId())).findFirst().orElseThrow(()->new BadRequestException("Question is not part of this exam"));QuestionOption option=null;if(ar.optionId()!=null)option=q.getOptions().stream().filter(o->o.getId().equals(ar.optionId())).findFirst().orElseThrow(()->new BadRequestException("Option does not belong to question"));StudentAnswer answer=a.getAnswers().stream().filter(x->x.getQuestion().getId().equals(q.getId())).findFirst().orElseGet(()->{StudentAnswer x=new StudentAnswer();x.setAttempt(a);x.setQuestion(q);a.getAnswers().add(x);return x;});answer.setSelectedOption(option);}return dto(attempts.save(a));}
 @Transactional public AttemptResponse submit(String email,Long id){Attempt a=owned(email,id);if(a.getStatus()!=Attempt.Status.IN_PROGRESS)return dto(a);LocalDateTime deadline=a.getStartedAt().plusMinutes(a.getExam().getDurationMinutes());if(LocalDateTime.now().isAfter(deadline))a.setStatus(Attempt.Status.EXPIRED);else a.setStatus(Attempt.Status.SUBMITTED);double score=0;for(Question q:a.getExam().getQuestions()){StudentAnswer ans=a.getAnswers().stream().filter(x->x.getQuestion().getId().equals(q.getId())).findFirst().orElse(null);if(ans!=null&&ans.getSelectedOption()!=null&&ans.getSelectedOption().isCorrect())ans.setAwardedMarks(q.getMarks());else if(ans!=null)ans.setAwardedMarks(0);if(ans!=null)score+=ans.getAwardedMarks();}a.setScore(score);double max=a.getExam().getMaximumMarks();a.setPercentage(max==0?0:Math.round(score/max*10000.0)/100.0);a.setPassed(a.getPercentage()>=a.getExam().getPassingPercentage());a.setSubmittedAt(LocalDateTime.now());return dto(attempts.save(a));}
 public List<AttemptResponse> mine(String email){AppUser u=users.findByEmailIgnoreCase(email).orElseThrow(()->new NotFoundException("User not found"));return attempts.findByUserIdOrderByStartedAtDesc(u.getId()).stream().map(this::dto).toList();}
 public ResultResponse result(String email,Long id,boolean admin){Attempt a=attempts.findById(id).orElseThrow(()->new NotFoundException("Attempt not found"));if(!admin&&!a.getUser().getEmail().equalsIgnoreCase(email))throw new org.springframework.security.access.AccessDeniedException("You cannot view another student's result");return new ResultResponse(a.getId(),a.getExam().getId(),a.getExam().getTitle(),a.getUser().getEmail(),a.getStatus().name(),a.getScore(),a.getExam().getMaximumMarks(),a.getPercentage(),a.isPassed(),a.getSubmittedAt());}
 public List<ResultResponse> allResults(){return attempts.findAll().stream().map(a->new ResultResponse(a.getId(),a.getExam().getId(),a.getExam().getTitle(),a.getUser().getEmail(),a.getStatus().name(),a.getScore(),a.getExam().getMaximumMarks(),a.getPercentage(),a.isPassed(),a.getSubmittedAt())).toList();}
 private Attempt owned(String email,Long id){Attempt a=attempts.findById(id).orElseThrow(()->new NotFoundException("Attempt not found"));if(!a.getUser().getEmail().equalsIgnoreCase(email))throw new org.springframework.security.access.AccessDeniedException("This attempt belongs to another user");return a;}
 private void ensureActive(Attempt a){if(a.getStatus()!=Attempt.Status.IN_PROGRESS)throw new BadRequestException("Attempt is already finalized");if(LocalDateTime.now().isAfter(a.getStartedAt().plusMinutes(a.getExam().getDurationMinutes())))throw new BadRequestException("Exam time has expired; submit the attempt to finalize it");}
 private AttemptResponse dto(Attempt a){return new AttemptResponse(a.getId(),a.getExam().getId(),a.getExam().getTitle(),a.getStatus().name(),a.getStartedAt(),a.getSubmittedAt(),a.getStartedAt().plusMinutes(a.getExam().getDurationMinutes()),a.getScore(),a.getPercentage(),a.isPassed());}}
